import hashlib,json
from botocore.exceptions import ClientError,EndpointConnectionError,ReadTimeoutError,ConnectionClosedError

def observe(source,destination,target_s3,read_sync,source_data_pool,bucket,key,approved_sha):
    if not isinstance(approved_sha,str)or len(approved_sha)!=64 or any(x not in '0123456789abcdef'for x in approved_sha):
        raise ValueError('approved SHA256')
    source_fsid=source.get_fsid();destination_fsid=destination.get_fsid()
    if source_fsid==destination_fsid:raise ValueError('different Ceph backends required for this exercise')
    rc,raw,error=source.mon_command(json.dumps({'prefix':'osd dump','format':'json'}),b'')
    if rc:raise RuntimeError('native OSD map query failed: '+str(error))
    pools=[row for row in json.loads(raw)['pools']if row['pool_name']==source_data_pool]
    if len(pools)!=1:raise ValueError('source data pool')
    pool=pools[0];source.wait_for_latest_osdmap();rows=[]
    for index in range(pool['pg_num']):
        pgid=str(pool['pool'])+'.'+format(index,'x')
        rc,raw,error=source.pg_command(pgid,json.dumps({'prefix':'query','pgid':pgid}),b'',timeout=3)
        if rc:raise RuntimeError('native source PG query failed: '+str(error))
        rows.append(json.loads(raw))
    source_clean=bool(rows)and all(set(row['state'].split('+'))=={'active','clean'}and len(set(row['acting']))==pool['size']for row in rows)
    metadata=read_sync('metadata');data=read_sync('data')
    verified=False
    try:
        response=target_s3.get_object(Bucket=bucket,Key=key)
        try:
            digest=hashlib.sha256()
            for chunk in iter(lambda:response['Body'].read(8192),b''):digest.update(chunk)
            verified=digest.hexdigest()==approved_sha
        finally:response['Body'].close()
    except ClientError as error:
        if error.response.get('Error',{}).get('Code')not in ('NoSuchBucket','NoSuchKey','404'):raise
    except (EndpointConnectionError,ReadTimeoutError,ConnectionClosedError):
        # Unavailable endpoint gives no proof of this object's replicated bytes.
        pass
    return {'source_fsid':source_fsid,'destination_fsid':destination_fsid,'source_pool_replicas':pool['size'],'source_pg_clean':source_clean,'metadata_status':metadata,'data_status':data,'object_verified':verified}

